const sysDIVE_LENS   = 0.75;
const sysDIVE_PULL_N = 8;   // gentle steps, and it stops at the first one that clears
const sysDIVE_PULL_K = 0.85;
const sysDIVE_EYE_CLEAR = 0.4;   // m of ground the eye must be standing clear of

